const defaultMemory = 32 * 1024 * 1024

type formBinding struct{}
type formPostBinding struct{}
type formMultipartBinding struct{}

// MaxMultipartMemory is the memory limit used when parsing multipart forms.
func MaxMultipartMemory() int64 {
	return defaultMemory
}

// IsMultipartContentType reports whether contentType refers to multipart form data.
func IsMultipartContentType(contentType string) bool {
	prefix := MIMEMultipartPOSTForm
	if contentType == prefix {
		return true
	}
	if len(contentType) > len(prefix) && contentType[:len(prefix)] == prefix {
		return true
	}
	return false
}

func (formBinding) Name() string {
	return "form"
}

func (formBinding) Bind(req *http.Request, obj interface{}) error {
	if err := req.ParseForm(); err != nil {
		return err
	}
	memory := MaxMultipartMemory()
	if IsMultipartContentType(req.Header.Get("Content-Type")) {
		memory = MaxMultipartMemory()
	}
	if err := req.ParseMultipartForm(memory); err != nil {
		if err != http.ErrNotMultipart {
			return err
		}
	}
	if err := mapRequestForm(obj, req.Form); err != nil {
		return err
	}
	return validate(obj)
}

func (formPostBinding) Name() string {
	return "form-urlencoded"
}

func (formPostBinding) Bind(req *http.Request, obj interface{}) error {
	if err := req.ParseForm(); err != nil {
		return err
	}
	if err := mapRequestForm(obj, req.PostForm); err != nil {
		return err
	}
	return validate(obj)
}

func (formMultipartBinding) Name() string {
	return "multipart/form-data"
}

func (formMultipartBinding) Bind(req *http.Request, obj interface{}) error {
	if err := req.ParseMultipartForm(MaxMultipartMemory()); err != nil {
		return err
	}
	if err := mappingByPtr(obj, (*multipartRequest)(req), "form"); err != nil {
		return err
	}

	return validate(obj)
}
